                "job_id": job.get("id"),
                "missing_paths": missing,
                "mismatches": mismatches,
                "status": "matched" if not missing and not mismatches else "mismatch",
            }
        )

    if any(job["status"] == "mismatch" for job in job_results):
        status = "mismatch"
    elif comparable_jobs == len(jobs) and jobs:
